; =============================================================================
; TONE DATABASE — AUXILIARY TABLES (ROM 0x855A48 - 0x87FFEF)
; =============================================================================
; Part of the tone database that SubCPU_Send_Payload copies to SubCPU RAM:
; ROM 0x830000-0x87FFFF -> SubCPU 0x50000-0x9FFFF (five 64KB E1 bulk transfers,
; see maincpu SubCPU_Send_Payload; SubCPU DSP_System_Init stores base 0x50000).
; All offsets inside the database are relative to ToneDB_Base (= ROM 0x830000,
; seen by the SubCPU at 0x50000).  The 64-entry directory at 0x830000 holds
; LE32 offsets to the structures below; the directory slot for each structure
; is noted as "dir +0xNN" in its header comment.
;
; STRUCTURE MAP OF THIS MODULE:
;   0x855A48  ToneDB_DefaultLayerParams      81 bytes        dir +0xAC
;   0x855A99  ToneDB_ToneIndexMapA           1024 x LE16     dir +0x0C
;   0x856299  ToneDB_ToneIndexMapB           1024 x LE16     dir +0x10
;   0x856A99  ToneDB_MixerDefaultTable       337 x 11 bytes  dir +0x18/+0x1C
;   0x857914  ToneDB_EnvDescTable            487 x 15 bytes  dir +0x30/34/38
;   0x85959D  ToneDB_ToneIndexMapC           1024 x LE16     dir +0x24/+0x9C
;   0x859D9D  ToneDB_ToneIndexMapD           1024 x LE16     dir +0x28/+0xA0
;   0x85A59D  ToneDB_DrumToneIndexMap        1024 x LE16     dir +0x2C/+0xA4
;   0x85AD9D  ToneDB_VelocityCurve_0..5      6 x 128 bytes  key->band maps
;   0x85B09D  ToneEnv_* data chunks          974 blobs, 32732 bytes
;   0x863079  DrumKit_* records              26 x 295 bytes
;   0x864E6F  PercInst_* records             610 x 58 bytes  dir +0x78
;   0x86D8A3  DrumKit_NoteMapA               4096 x LE16     dir +0x74
;   0x86F8A3  ToneDB_PercMixerDefaultTable   142 x 11 bytes  dir +0x20
;   0x86FEBD  ToneDB_PercSourceIndexMapA     1024 x LE16     dir +0x14
;   0x8706BD  DrawbarPreset_Jazz/_Rock       2 x 426 bytes
;   0x870A11  DrawbarPreset_EnvDescTable     4 x 15 bytes    dir +0x70
;   0x870A4D  DrawbarPreset_EnvData_0..2     8772 bytes
;   0x872C91  ToneDB_SourceNameList1         333 x 16 bytes  dir +0x50
;   0x874161  ToneDB_SourceIndexMapA         1024 x LE16     dir +0x44
;   0x874961  ToneDB_SourceIndexMapB         1024 x LE16     dir +0x48
;   0x875161  ToneDB_SourceList1_Footer      17 bytes        dir +0x54
;   0x875172  ToneDB_SourceNameList2         339 x 16 bytes  dir +0x64
;   0x8766A2  ToneDB_SourceIndexMapC         1024 x LE16     dir +0x58
;   0x876EA2  ToneDB_SourceIndexMapD         1024 x LE16     dir +0x5C
;   0x8776A2  ToneDB_SourceList2_Footer      17 bytes        dir +0x68
;   0x8776B3  ToneDB_PercSourceNameList1     141 x 16 bytes  dir +0x8C
;   0x877F83  ToneDB_PercList1_Footer        14 bytes        dir +0x90
;   0x877F91  ToneDB_PercSourceIndexMapB     1024 x LE16     dir +0x4C
;   0x878791  ToneDB_PercSourceNameList2     144 x 16 bytes  dir +0x94
;   0x879091  ToneDB_PercSourceIndexMapC     1024 x LE16     dir +0x60
;   0x879891  ToneDB_PercList2_Footer        14 bytes        dir +0x98
;   0x87989F  ToneDB_DrumSourceNameList      424 x 16 bytes  dir +0x80
;   0x87B31F  ToneDB_DrumList_Footer         3 bytes         dir +0x84
;   0x87B322  DrumKit_NoteMapB               4096 x LE16     dir +0x7C
;   0x87D322  PercName_Pack                  610 x 10 chars  dir +0xB0
;   0x87EAF6  unused fill (0xFF)             5370 bytes
;
; COUNT RELATIONS (evidence for the cross-indexing):
;   ToneDB_SourceIndexMapA/B  max value 332/331 < 333 = SourceNameList1 count
;   ToneDB_SourceIndexMapC/D  max value 338/337 < 339 = SourceNameList2 count
;   ToneDB_PercSourceIndexMapA/B max 141/140 <= 141 = PercSourceNameList1 count
;   ToneDB_PercSourceIndexMapC max 143 < 144 = PercSourceNameList2 count
;   DrumKit_NoteMapA/B  entries all < 610 = PercInst record count
;   PercName_Pack has 610 entries = PercInst record count; entries 0-423 are
;     10-char abbreviations, in order, of the 424-entry ToneDB_DrumSourceNameList
;   Each *_Footer starts with an LE16 equal to the record count of the name
;     list opening its group ({names, index maps..., footer} chain of 5 groups)
; =============================================================================

	.org 0x855A48 - 0x800000, 0xff

; Typed zone-record rows (ToneEnv_*_B and DrawbarPreset_EnvData_*): one row =
; one zone record, fields as documented in the ToneEnv chunk header below.
;   ToneEnvZone4  selector (LE16), level-field byte, s8 fine trim
;   ToneEnvZone6  the same + s16 coarse trim (8.8 semitones)
.macro ToneEnvZone4 sel, fld, trim
	.short	\sel
	.byte	\fld, \trim
.endm
.macro ToneEnvZone6 sel, fld, trim, coarse
	.short	\sel
	.byte	\fld, \trim
	.short	\coarse
.endm

; Offsets stored inside the tone database are relative to its load base
; ToneDB_Base (ROM 0x830000 = SubCPU RAM 0x50000), defined as a label in
; tone_database_directory.s.

; -----------------------------------------------------------------------------
; 81-byte parameter block (dir +0xAC).  81 bytes is exactly the per-layer
; quantum of the variable-length tone records at 0x8324D4 (record strides are
; 102+81k bytes), so this is most likely the default/template layer parameter
; set.  Values follow MIDI conventions: 0x40 = center, 0x7f = max, 100/60/40 =
; typical level defaults.
ToneDB_DefaultLayerParams:
	.byte	0x00, 0x40, 0x00, 0x00, 0x00, 0x00, 0x00, 0x32, 0x00, 0x1e, 0x00, 0x1e, 0x00, 0x1e, 0x00, 0x1e
	.byte	0x00, 0x00, 0x00, 0x42, 0x00, 0x00, 0x00, 0x5a, 0x14, 0x60, 0x42, 0x18, 0x66, 0x00, 0x00, 0x00
	.byte	0x7f, 0x7f, 0x00, 0x00, 0x7f, 0x7f, 0x00, 0x00, 0x64, 0x3c, 0x64, 0x50, 0x64, 0x28, 0x0a, 0x00
	.byte	0x42, 0x18, 0x7f, 0x00, 0x00, 0x00, 0x61, 0x14, 0x00, 0x42, 0x00, 0x7f, 0x00, 0x00, 0x00, 0x1e
	.byte	0x00, 0x1e, 0x00, 0x1e, 0x00, 0x1e, 0x00, 0x00, 0x00, 0x42, 0x00, 0x00, 0x00, 0x60, 0x02, 0x40
	.byte	0x87

